#!/usr/bin/env node
/**
 * Generate the full Tauri icon set from a single PNG source.
 *
 * Usage:
 *   node scripts/tauri-icons.mjs [--source path/to/source.png]
 *
 * Defaults:
 *   --source  the first *.png found at the project root (prefers icon/logo/home/editor)
 *
 * Output:
 *   src-tauri/icons/icon-source.png  (cropped/resized to 1024x1024)
 *   src-tauri/icons/*                 (generated by `tauri icon`)
 *
 * Requirements:
 *   - sharp (devDependency)
 *   - @tauri-apps/cli (devDependency)
 */

import { execFileSync } from 'node:child_process';
import { existsSync, statSync } from 'node:fs';
import { mkdir, readdir } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';
import sharp from 'sharp';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const ICONS_DIR = path.join(ROOT, 'src-tauri', 'icons');

function parseArgs(argv) {
  const out = { source: null };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--source' && argv[i + 1]) {
      out.source = argv[++i];
    } else if (!out.source && argv[i] && !argv[i].startsWith('--')) {
      out.source = argv[i];
    }
  }
  return out;
}

async function findDefaultSource() {
  const candidates = await readdir(ROOT, { withFileTypes: true });
  const pngs = candidates.filter(e => e.isFile() && e.name.toLowerCase().endsWith('.png')).map(e => e.name);
  if (pngs.length === 0) {
    throw new Error('No PNG found at project root. Pass --source path/to/file.png');
  }
  const preferred = ['icon.png', 'logo.png', 'home.png', 'editor.png'];
  for (const p of preferred) {
    if (pngs.includes(p)) return p;
  }
  return pngs[0];
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const sourceRel = args.source || (await findDefaultSource());
  const sourceAbs = path.resolve(ROOT, sourceRel);
  if (!existsSync(sourceAbs)) {
    throw new Error('Source not found: ' + sourceAbs);
  }
  if (statSync(sourceAbs).size === 0) {
    throw new Error('Source is empty: ' + sourceAbs);
  }
  const meta = await sharp(sourceAbs).metadata();
  if (!meta.width || !meta.height) {
    throw new Error('Could not read source image dimensions: ' + sourceAbs);
  }
  console.log(`Source: ${sourceRel} (${meta.width}x${meta.height})`);

  // Crop to square (center) and resize to 1024x1024.
  await mkdir(ICONS_DIR, { recursive: true });
  const target = path.join(ICONS_DIR, 'icon-source.png');
  const size = Math.min(meta.width, meta.height);
  const left = Math.floor((meta.width - size) / 2);
  const top = Math.floor((meta.height - size) / 2);
  await sharp(sourceAbs)
    .extract({ left, top, width: size, height: size })
    .resize(1024, 1024)
    .png()
    .toFile(target);
  console.log('Wrote 1024x1024 master: ' + path.relative(ROOT, target));

  // Delegate the rest to Tauri's icon generator.
  console.log('Running tauri icon...');
  execFileSync('npx', ['@tauri-apps/cli', 'icon', target], {
    cwd: path.join(ROOT, 'src-tauri'),
    stdio: 'inherit',
    shell: process.platform === 'win32',
  });
  console.log('Done. Icons in src-tauri/icons/.');
}

main().catch(e => {
  console.error(e instanceof Error ? e.message : String(e));
  process.exit(1);
});
